import numpy as np
import pandas as pd

def signal_report(signal, ret, horizons, q=5, step=21):
    ic = ic_by_horizon(signal, ret, horizons, step)
    fwd = forward_returns(ret, step)
    qr = quantile_returns(signal.iloc[::step], fwd.iloc[::step], q)
    return {"ic": {int(h): {"mean": float(r["mean"]), "t": float(r["t"]), "n": int(r["n"])}
                   for h, r in ic.iterrows()},
            "quintiles": [round(float(v), 6) for v in qr.mean()],
            "spread": spread_stats(qr, 252 / step)}
